const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // A central point in Hood Canal, Washington, USA.
    const hoodCanalPoint = ee.Geometry.Point([-122.86, 47.45]);
    // Define the region of interest as a buffer around the point to represent a small area of the canal.
    const roi = hoodCanalPoint.buffer(1000); // 1 km buffer

    const dateRange2021 = { start: '2021-08-20', end: '2021-08-31' };
    const dateRange2022 = { start: '2022-08-20', end: '2022-08-31' };

    const SCALE = 100; // Sentinel-2 B2 resolution is 10m. Using 100m for faster processing and average.

    // Sentinel-2 Cloud Masking Function
    function s2CloudMask(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000) // Scale to 0-1 reflectance
                  .select('B2') // Only select the blue band
                  .copyProperties(image, ['system:time_start']);
    }

    // 2. Data Acquisition & Check for 2021
    let collection2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(roi)
      .filterDate(dateRange2021.start, dateRange2021.end)
      .map(s2CloudMask);

    const size2021 = await collection2021.size().getInfo();
    if (size2021 === 0) {
      console.log("No Sentinel-2 images found for late August 2021.");
      console.log("C1");
      return;
    }
    console.log(`2021 Images: ${size2021}`);

    // Compute median composite for 2021
    const image2021 = collection2021.median();

    // 3. Data Acquisition & Check for 2022
    let collection2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(roi)
      .filterDate(dateRange2022.start, dateRange2022.end)
      .map(s2CloudMask);

    const size2022 = await collection2022.size().getInfo();
    if (size2022 === 0) {
      console.log("No Sentinel-2 images found for late August 2022.");
      console.log("C1");
      return;
    }
    console.log(`2022 Images: ${size2022}`);

    // Compute median composite for 2022
    const image2022 = collection2022.median();

    // Calculate pixel count for 2021
    const count2021 = await image2021.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: SCALE,
      maxPixels: 1e9
    }).get('B2').getInfo();

    if (count2021 === 0) {
      console.log("No valid pixels after masking for 2021.");
      console.log("C2");
      return;
    }

    // Calculate pixel count for 2022
    const count2022 = await image2022.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: SCALE,
      maxPixels: 1e9
    }).get('B2').getInfo();

    if (count2022 === 0) {
      console.log("No valid pixels after masking for 2022.");
      console.log("C2");
      return;
    }

    // 4. Calculation - Mean B2 (Blue) reflectance
    const meanB2_2021 = await image2021.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: SCALE,
      maxPixels: 1e9
    }).get('B2').getInfo();

    const meanB2_2022 = await image2022.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: SCALE,
      maxPixels: 1e9
    }).get('B2').getInfo();

    // 5. Validation & Final Answer
    if (meanB2_2021 === null || isNaN(meanB2_2021) || meanB2_2022 === null || isNaN(meanB2_2022)) {
      console.log("Calculation resulted in None/NaN values.");
      console.log("C3");
      return;
    }

    console.log(`Hood Canal (late Aug 2021) mean B2: ${meanB2_2021.toFixed(4)} (Pixels: ${count2021})`);
    console.log(`Hood Canal (late Aug 2022) mean B2: ${meanB2_2022.toFixed(4)} (Pixels: ${count2022})`);

    // "Brighter blue color" means higher B2 reflectance.
    // "Noticeable larger bloom" implies a significant increase.
    // Let's define "noticeable" as at least a 5% increase in B2 reflectance.
    const percentageIncrease = ((meanB2_2022 - meanB2_2021) / meanB2_2021) * 100;

    console.log(`Percentage increase in B2: ${percentageIncrease.toFixed(2)}%`);

    if (percentageIncrease > 5) { // Threshold for "noticeable larger bloom"
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    console.log("D"); // General error, potentially due to incorrect method/syntax or memory.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
